"""Learning stages and concepts for learning Claude Code from scratch to advanced, with TPM takeaways.

Stages run from basics to intermediate to advanced. Each concept has: gist,
purpose (why it matters), a plain-words explanation, an example, three
insights, two experiments, three timed next steps, a metric to track, a TPM
takeaway, the official docs pages it follows, a copy-paste snippet, the best
resources (keys into resources.RESOURCES) and three quiz questions.

All text is original. Feature facts (commands, flags, settings, file paths)
follow the official Claude Code docs at code.claude.com as reviewed on
REVIEWED; Claude Code ships often, so check the linked page when something
looks different on your machine.
"""

REVIEWED = "14 October 2026"
DOCS_BASE = "https://code.claude.com/docs/en/"

TOP_20_NOTE = (
    "\"Top 20%\" here is a curated editorial judgement, not a measured ranking. The concepts are the ones the official "
    "docs and Anthropic's own guides keep coming back to (context, verification, CLAUDE.md, permissions, skills, hooks, "
    "MCP, subagents, automation and cost), because they give the most results per hour of learning. Summaries are short "
    "original paraphrases. Claude Code changes quickly, and prices, course catalogs and certifications change too, so "
    "check the linked official page before you rely on a detail."
)

STAGE_LEVELS = ["🟢 Basics", "🟡 Intermediate", "🔴 Advanced"]


def q(question, options, answer, why):
    """One multiple-choice question; `answer` is the index of the correct option."""
    return {"q": question, "options": options, "answer": answer, "why": why}


def topic(icon, title, gist, purpose, plain, example, insights, experiments, actions, metric, tpm, docs, snippet, resources, quiz):
    return {
        "icon": icon, "title": title, "gist": gist, "purpose": purpose, "plain": plain, "example": example,
        "insights": insights, "experiments": experiments, "actions": actions, "metric": metric, "tpm": tpm,
        "docs": docs, "snippet": snippet, "resources": resources, "quiz": quiz,
    }


